:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --bg-hero: #0f3460;
  --bg-detail: #1e1e38;
  --bg-footer: #12122a;
  --accent-purple: #7c3aed;
  --accent-cyan: #06b6d4;
  --accent-danger: #ef4444;
  --text-primary: #f1f5f9;
  --text-muted: #94a3b8;
  --text-label: #7c8db5;
  --border-subtle: #2e2e50;
  --badge-bg: #7f1d1d;
  --badge-text: #fca5a5;
  --price-green: #34d399;
}

.booking-card {
  width: 440px;
  background: var(--bg-card);
  border-radius: 14px;
  border: 1px solid var(--border-subtle);
  overflow: hidden;
  margin: 0 auto;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-header);
  padding: 8px 14px;
  border-bottom: 1px solid var(--border-subtle);
}

.booking-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--accent-cyan);
  text-transform: uppercase;
}

.booking-id {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
}

.room-hero {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-hero);
  padding: 10px 14px;
  border-bottom: 1px solid var(--border-subtle);
}

.room-icon {
  font-size: 28px;
  line-height: 1;
  flex-shrink: 0;
}

.room-info {
  flex: 1;
}

.room-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 2px 0;
  line-height: 1.2;
}

.room-tagline {
  font-size: 11px;
  color: var(--text-muted);
  margin: 0;
}

.difficulty-badge {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  padding: 3px 8px;
  border-radius: 5px;
  background: var(--badge-bg);
  color: var(--badge-text);
  border: 1px solid var(--accent-danger);
  flex-shrink: 0;
}

.details-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.detail-item {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  background: var(--bg-detail);
  padding: 9px 12px;
}

.detail-icon {
  font-size: 14px;
  line-height: 1;
}

.detail-label {
  font-size: 10px;
  color: var(--text-label);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.detail-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-footer);
  padding: 10px 14px;
}

.host-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.host-label {
  font-size: 10px;
  color: var(--text-label);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.host-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--accent-purple);
}

.price-row {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.price-label {
  font-size: 10px;
  color: var(--text-label);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.price-amount {
  font-size: 18px;
  font-weight: 800;
  color: var(--price-green);
}
